import { action, v } from "@wizard/sdk";

export default action({
  args: {},
  handler: async (ctx) => {
    const holder = { holder_phone: "x" };
    await ctx.http.fetch("https://api.telegram.org/botsecret://bot_key/sendMessage", {
      method: "POST",
      body: JSON.stringify({ chat_id: "1", text: `Телефон: ${holder.holder_phone}` }),
    });
    return null;
  },
});
